pf() { make -C src -f Makefile -f /tmp/pf.mk pf "$@" 2>/dev/null; }
getv() { # getv <var> [make args...]
    local v="$1"; shift
    if [ "$#" -eq 0 ]; then pf | sed -n "s/^$v=\[\(.*\)\]$/\1/p"
    else pf "$@" | sed -n "s/^$v=\[\(.*\)\]$/\1/p"; fi
}

